   201	            | RequestSnapshotState::Cancelled
   202	            | RequestSnapshotState::Completed => continue,
   203	        };
   204	        let (session_title, project) =
   205	            session_attention_metadata(sessions, request.session_id.as_deref());
   206	        let detail = request
   207	            .message
   208	            .as_deref()
   209	            .map(str::trim)
   210	            .filter(|message| !message.is_empty())
   211	            .map(bounded_detail)
   212	            .unwrap_or_else(|| state.label().to_string());
   213	        items.push(IslandAttentionItem {
   214	            id: format!("request:{}", request.request_id),
   215	            request_id: request.request_id.clone(),
   216	            session_id: request.session_id.clone(),
   217	            session_title,
   218	            project,
   219	            tool: None,
   220	            detail,
   221	            updated_at: request_updated_at(request),
   222	            state,
   223	        });
   224	    }
   225	
   226	    items.sort_by(|a, b| {
   227	        a.state
   228	            .rank()
   229	            .cmp(&b.state.rank())
   230	            .then_with(|| b.updated_at.cmp(&a.updated_at))
   231	            .then_with(|| a.id.cmp(&b.id))
   232	    });
   233	    items
   234	}
