   236	fn recently_updated(updated_at: &str) -> bool {
   237	    #[cfg(target_arch = "wasm32")]
   238	    {
   239	        is_recent(updated_at)
   240	    }
   241	    #[cfg(not(target_arch = "wasm32"))]
   242	    {
   243	        // Browser time is intentionally unavailable in native unit tests.
   244	        // Sorting remains fully deterministic there; production uses the
   245	        // shared sessions-panel recency window above.
   246	        let _ = updated_at;
   247	        false
   248	    }
