   251	/// Project daemon sessions into the compact metadata used by the Island.
   252	pub(crate) fn derive_island_sessions(
   253	    sessions: &[SessionSummary],
   254	    projects: &[ProjectInfo],
   255	    focused_id: Option<&str>,
   256	) -> Vec<IslandSession> {
   257	    let mut items: Vec<_> = sessions
   258	        .iter()
   259	        .map(|session| {
   260	            let root = session_root(session).to_string();
   261	            let project = session
   262	                .owning_project
   263	                .as_ref()
   264	                .map(|owner| {
   265	                    if owner.name.trim().is_empty() {
   266	                        owner.id.clone()
   267	                    } else {
   268	                        owner.name.trim().to_string()
   269	                    }
   270	                })
   271	                .or_else(|| {
   272	                    project_for_root(projects, &root).map(|project| {
   273	                        if project.name.trim().is_empty() {
   274	                            project.id.clone()
   275	                        } else {
   276	                            project.name.trim().to_string()
   277	                        }
   278	                    })
   279	                });
   280	            let (origin, title) = split_origin(&session.title);
   281	            let is_focused = focused_id == Some(session.id.as_str());
   282	            let priority = if is_focused {
   283	                IslandPriority::Focused
   284	            } else if recently_updated(&session.updated_at) {
   285	                IslandPriority::Recent
   286	            } else {
   287	                IslandPriority::Background
   288	            };
   289	
   290	            IslandSession {
   291	                id: session.id.clone(),
   292	                title,
   293	                project,
   294	                cwd: root,
   295	                branch: session.git_branch.clone().filter(|value| !value.is_empty()),
   296	                origin,
   297	                updated_at: session.updated_at.clone(),
   298	                turn_count: session.turn_count,
   299	                is_focused,
   300	                priority,
   301	            }
   302	        })
   303	        .collect();
   304	
   305	    items.sort_by(|a, b| {
   306	        b.is_focused
   307	            .cmp(&a.is_focused)
   308	            .then_with(|| b.updated_at.cmp(&a.updated_at))
   309	            .then_with(|| a.title.to_lowercase().cmp(&b.title.to_lowercase()))
   310	            .then_with(|| a.id.cmp(&b.id))
   311	    });
   312	    items
   313	}
