   315	/// Normalized session document shared by Browse filtering and `Cmd/Ctrl+P`.
   316	pub(crate) fn island_search_text(item: &IslandSession) -> String {
   317	    let state = match item.priority {
   318	        IslandPriority::Focused => "focused",
   319	        IslandPriority::Recent => "recent",
