   412	
   413	fn next_index(index: usize, len: usize) -> usize {
   414	    if len == 0 {
   415	        0
   416	    } else {
   417	        (index + 1) % len
   418	    }
   419	}
   420	
   421	fn previous_index(index: usize, len: usize) -> usize {
   422	    if len == 0 {
   423	        0
   424	    } else {
   425	        (index + len - 1) % len
   426	    }
   427	}
