 315	/// Normalized session document shared by Browse filtering and `Cmd/Ctrl+P`.
 316	pub(crate) fn island_search_text(item: &IslandSession) -> String {
 317	    let state = match item.priority {
 318	        IslandPriority::Focused => "focused",
 319	        IslandPriority::Recent => "recent",
 320	        IslandPriority::Background => "background",
 321	    };
 322	    let project = item.project.as_deref().unwrap_or_default();
 323	    let branch = item.branch.as_deref().unwrap_or_default();
 324	    let origin = item.origin.as_deref().unwrap_or_default();
 325	    format!(
 326	        "{} {} project:{} {} {} {} {} {} turns",
 327	        item.title, project, project, item.cwd, branch, origin, state, item.turn_count
 328	    )
 329	    .to_lowercase()
 330	}
