 332	/// Search the Island corpus while preserving derivation order for an empty
 333	/// query and using focus/recency only as small tie-breaks for real queries.
 334	pub(crate) fn search_island(query: &str, items: &[IslandSession]) -> Vec<IslandResult> {
 335	    let query = query.trim();
 336	    if query.is_empty() {
 337	        return items.iter().cloned().map(IslandResult::Session).collect();
 338	    }
 339	
 340	    let query_lower = query.to_lowercase();
 341	    let mut scored: Vec<(u8, f64, usize, IslandSession)> = items
 342	        .iter()
 343	        .enumerate()
 344	        .filter_map(|(index, item)| {
 345	            let document_score = fuzzy_score(query, &island_search_text(item))?;
 346	            let title = item.title.to_lowercase();
 347	            let title_score = fuzzy_score(query, &item.title);
 348	            let project = item.project.as_deref().map(str::to_lowercase);
 349	            let project_score = project
 350	                .as_deref()
 351	                .and_then(|project| fuzzy_score(query, project));
 352	
 353	            // Match category is a strict tier; fuzzy score only orders items
 354	            // inside a tier, so a long fuzzy title can never outrank an exact
 355	            // project (and metadata can never outrank a title/project match).
 356	            let (tier, mut score) = if title == query_lower {
 357	                (6, title_score.unwrap_or(document_score))
 358	            } else if title.starts_with(&query_lower) {
 359	                (5, title_score.unwrap_or(document_score))
 360	            } else if project.as_deref() == Some(query_lower.as_str()) {
 361	                (4, project_score.unwrap_or(document_score))
 362	            } else if project
 363	                .as_deref()
 364	                .is_some_and(|project| project.starts_with(&query_lower))
 365	            {
 366	                (3, project_score.unwrap_or(document_score))
 367	            } else if let Some(title_score) = title_score {
 368	                (2, title_score)
 369	            } else if let Some(project_score) = project_score {
 370	                (1, project_score)
 371	            } else {
 372	                (0, document_score)
 373	            };
 374	            score += match item.priority {
 375	                IslandPriority::Focused => 2.0,
 376	                IslandPriority::Recent => 1.0,
 377	                IslandPriority::Background => 0.0,
 378	            };
 379	            Some((tier, score, index, item.clone()))
 380	        })
 381	        .collect();
 382	
 383	    scored.sort_by(|a, b| {
 384	        b.0.cmp(&a.0)
 385	            .then_with(|| b.1.partial_cmp(&a.1).unwrap_or(std::cmp::Ordering::Equal))
 386	            .then_with(|| a.2.cmp(&b.2))
 387	            .then_with(|| a.3.id.cmp(&b.3.id))
 388	    });
 389	    scored
 390	        .into_iter()
 391	        .map(|(_, _, _, item)| IslandResult::Session(item))
 392	        .collect()
 393	}
 394	
 395	fn option_id(session_id: &str) -> String {
 396	    let encoded = session_id
 397	        .as_bytes()
 398	        .iter()
 399	        .map(|byte| format!("{byte:02x}"))
 400	        .collect::<String>();
 401	    format!("island-option-{encoded}")
 402	}
 403	
 404	fn attention_panel_id(item_id: &str) -> String {
 405	    let encoded = item_id
 406	        .as_bytes()
 407	        .iter()
 408	        .map(|byte| format!("{byte:02x}"))
 409	        .collect::<String>();
 410	    format!("island-attention-{encoded}")
 411	}
 412	
 413	fn next_index(index: usize, len: usize) -> usize {
 414	    if len == 0 {
 415	        0
 416	    } else {
 417	        (index + 1) % len
 418	    }
 419	}
 420	
 421	fn previous_index(index: usize, len: usize) -> usize {
 422	    if len == 0 {
 423	        0
 424	    } else {
 425	        (index + len - 1) % len
 426	    }
 427	}
