 429	#[component]
 430	pub fn Island(
 431	    daemon: Daemon,
 432	    mode: RwSignal<IslandMode>,
 433	    focus_request: RwSignal<u64>,
 434	    on_open: Callback<IslandMode>,
 435	) -> impl IntoView {
 436	    let query = RwSignal::new(String::new());
 437	    let selected_index = RwSignal::new(0usize);
 438	    let previous_mode = RwSignal::new(IslandMode::Closed);
 439	    let previous_focus = StoredValue::new_local(None::<web_sys::HtmlElement>);
 440	    let last_focus_request = RwSignal::new(0u64);
 441	    let recency_tick = RwSignal::new(0u64);
 442	    let expanded_attention = RwSignal::new(None::<String>);
 443	    let input_ref: NodeRef<leptos::html::Input> = NodeRef::new();
 444	    let chip_ref: NodeRef<leptos::html::Button> = NodeRef::new();
 445	    let popover_ref: NodeRef<leptos::html::Section> = NodeRef::new();
 446	
 447	    #[cfg(target_arch = "wasm32")]
 448	    let recency_interval =
 449	        send_wrapper::SendWrapper::new(gloo_timers::callback::Interval::new(60_000, move || {
 450	            recency_tick.update(|tick| *tick = tick.wrapping_add(1))
 451	        }));
 452	    #[cfg(target_arch = "wasm32")]
 453	    on_cleanup(move || drop(recency_interval));
 454	
 455	    #[cfg(target_arch = "wasm32")]
 456	    let attention_interval = {
 457	        let daemon = daemon.clone();
 458	        send_wrapper::SendWrapper::new(gloo_timers::callback::Interval::new(3_000, move || {
 459	            daemon.fetch_attention();
 460	        }))
 461	    };
 462	    #[cfg(target_arch = "wasm32")]
 463	    on_cleanup(move || drop(attention_interval));
 464	
 465	    let session_list = daemon.session_list;
 466	    let request_list = daemon.request_list;
 467	    let permission_list = daemon.permission_list;
 468	    let projects = daemon.projects;
 469	    let focused_id = daemon.session_id;
 470	    let daemon = StoredValue::new(daemon);
 471	
 472	    // The closed chip is an ambient session surface, not merely an overlay
 473	    // trigger. Prime its catalogue on mount so a restored focused session and
 474	    // recent count render without requiring the operator to open Search first.
 475	    // Opening still refreshes both sources below to avoid stale browse results.
 476	    {
 477	        let daemon = daemon.get_value();
 478	        daemon.fetch_sessions();
 479	        daemon.fetch_projects();
 480	        daemon.fetch_attention();
 481	    }
 482	
 483	    let sessions = Memo::new(move |_| {
 484	        let _ = recency_tick.get();
 485	        derive_island_sessions(
 486	            &session_list.get(),
 487	            &projects.get(),
 488	            focused_id.get().as_deref(),
 489	        )
 490	    });
 491	    let attention_items = Memo::new(move |_| {
 492	        derive_attention_items(&request_list.get(), &permission_list.get(), &sessions.get())
 493	    });
 494	    let needs_human_count = Memo::new(move |_| {
 495	        attention_items
 496	            .get()
 497	            .iter()
 498	            .filter(|item| {
 499	                matches!(
 500	                    item.state,
 501	                    IslandAttentionState::NeedsHuman | IslandAttentionState::Failed
 502	                )
 503	            })
 504	            .count()
 505	    });
 506	    let running_count = Memo::new(move |_| {
 507	        attention_items
 508	            .get()
 509	            .iter()
 510	            .filter(|item| {
 511	                matches!(
 512	                    item.state,
 513	                    IslandAttentionState::Running | IslandAttentionState::Cancelling
 514	                )
 515	            })
 516	            .count()
 517	    });
 518	    let results = Memo::new(move |_| {
 519	        let mut matches = search_island(&query.get(), &sessions.get());
 520	        if mode.get() == IslandMode::Search {
 521	            matches.truncate(20);
 522	        }
 523	        matches
 524	    });
 525	
 526	    Effect::new(move |_| {
 527	        let next = mode.get();
 528	        let request = focus_request.get();
 529	        let previous = previous_mode.get_untracked();
 530	        let previous_request = last_focus_request.get_untracked();
 531	        if next != IslandMode::Closed && previous == IslandMode::Closed {
 532	            let active = web_sys::window()
 533	                .and_then(|window| window.document())
 534	                .and_then(|document| document.active_element())
 535	                .and_then(|element| element.dyn_into::<web_sys::HtmlElement>().ok());
 536	            previous_focus.set_value(active);
 537	            query.set(String::new());
 538	            selected_index.set(0);
 539	            expanded_attention.set(None);
 540	            let daemon = daemon.get_value();
 541	            daemon.fetch_sessions();
 542	            daemon.fetch_projects();
 543	            daemon.fetch_attention();
 544	        }
 545	        let should_focus = next != IslandMode::Closed
 546	            && (previous == IslandMode::Closed || next != previous || request != previous_request);
 547	        if should_focus {
 548	            request_animation_frame(move || {
 549	                if let Some(input) = input_ref.get() {
 550	                    let _ = input.focus();
 551	                    if next == IslandMode::Search {
 552	                        input.select();
 553	                    }
 554	                }
 555	            });
 556	        } else if next == IslandMode::Closed && previous != IslandMode::Closed {
 557	            request_animation_frame(move || {
 558	                if let Some(element) = previous_focus.get_value().filter(|el| el.is_connected()) {
 559	                    let _ = element.focus();
 560	                } else if let Some(chip) = chip_ref.get() {
 561	                    let _ = chip.focus();
 562	                }
 563	            });
 564	        }
 565	        previous_mode.set(next);
 566	        last_focus_request.set(request);
 567	    });
 568	
 569	    Effect::new(move |_| {
 570	        let len = results.get().len();
 571	        if len == 0 || selected_index.get() >= len {
 572	            selected_index.set(0);
 573	        }
 574	    });
 575	
 576	    let selected_option_id = move || {
 577	        results
 578	            .get()
 579	            .get(selected_index.get())
 580	            .map(|result| match result {
 581	                IslandResult::Session(item) => option_id(&item.id),
 582	            })
 583	            .unwrap_or_default()
 584	    };
 585	    let close = move || mode.set(IslandMode::Closed);
 586	    let on_keydown = move |event: KeyboardEvent| {
 587	        if mode.get_untracked() == IslandMode::Closed || event.is_composing() {
 588	            return;
 589	        }
 590	        let key = event.key();
 591	        if key == "Escape" {
 592	            event.prevent_default();
 593	            event.stop_propagation();
 594	            close();
 595	            return;
 596	        }
 597	        if key == "Tab" {
 598	            // Phase 2 adds real disclosure/action controls. Keep them inside the
 599	            // modal focus loop while leaving session rows on the combobox's
 600	            // active-descendant path.
 601	            event.prevent_default();
 602	            let mut focusable = Vec::<web_sys::HtmlElement>::new();
 603	            if let Some(popover) = popover_ref.get() {
 604	                if let Ok(nodes) = popover.query_selector_all(
 605	                    ".island-search__input, .island-attention__summary, .island-attention__open:not([disabled])",
 606	                ) {
 607	                    for index in 0..nodes.length() {
 608	                        if let Some(element) = nodes
 609	                            .item(index)
 610	                            .and_then(|node| node.dyn_into::<web_sys::HtmlElement>().ok())
 611	                        {
 612	                            focusable.push(element);
 613	                        }
 614	                    }
 615	                }
 616	            }
 617	            if focusable.is_empty() {
 618	                if let Some(input) = input_ref.get() {
 619	                    let _ = input.focus();
 620	                }
 621	                return;
 622	            }
 623	            let current = event
 624	                .target()
 625	                .and_then(|target| target.dyn_into::<web_sys::Node>().ok());
 626	            let current_index = focusable
 627	                .iter()
 628	                .position(|element| {
 629	                    element
 630	                        .clone()
 631	                        .unchecked_into::<web_sys::Node>()
 632	                        .is_same_node(current.as_ref())
 633	                })
 634	                .unwrap_or(0);
 635	            let next = if event.shift_key() {
 636	                (current_index + focusable.len() - 1) % focusable.len()
 637	            } else {
 638	                (current_index + 1) % focusable.len()
 639	            };
 640	            let _ = focusable[next].focus();
 641	            return;
 642	        }
 643	
 644	        // Disclosure buttons use native Enter/Space activation. Session arrow
 645	        // navigation and Enter-to-focus apply only while the combobox owns DOM
 646	        // focus, preventing a disclosure keypress from switching another row.
 647	        let from_search = event
 648	            .target()
 649	            .and_then(|target| target.dyn_into::<web_sys::HtmlElement>().ok())
 650	            .is_some_and(|element| element.class_list().contains("island-search__input"));
 651	        if !from_search {
 652	            return;
 653	        }
 654	
 655	        let len = results.get_untracked().len();
 656	        match key.as_str() {
 657	            "ArrowDown" => {
 658	                event.prevent_default();
 659	                selected_index.update(|index| *index = next_index(*index, len));
 660	                request_animation_frame(move || {
 661	                    let id = selected_option_id();
 662	                    if let Some(option) = web_sys::window()
 663	                        .and_then(|window| window.document())
 664	                        .and_then(|document| document.get_element_by_id(&id))
 665	                    {
 666	                        option.scroll_into_view();
 667	                    }
 668	                });
 669	            }
 670	            "ArrowUp" => {
 671	                event.prevent_default();
 672	                selected_index.update(|index| *index = previous_index(*index, len));
 673	                request_animation_frame(move || {
 674	                    let id = selected_option_id();
 675	                    if let Some(option) = web_sys::window()
 676	                        .and_then(|window| window.document())
 677	                        .and_then(|document| document.get_element_by_id(&id))
 678	                    {
 679	                        option.scroll_into_view();
 680	                    }
 681	                });
 682	            }
 683	            "Enter" => {
 684	                event.prevent_default();
 685	                if let Some(IslandResult::Session(item)) =
 686	                    results.get_untracked().get(selected_index.get_untracked())
 687	                {
 688	                    daemon
 689	                        .get_value()
 690	                        .switch_session(item.id.clone(), item.title.clone());
 691	                    close();
 692	                }
 693	            }
 694	            _ => {}
 695	        }
 696	    };
 697	
 698	    let focused_session = Memo::new(move |_| {
 699	        sessions
 700	            .get()
 701	            .into_iter()
 702	            .find(|session| session.is_focused)
 703	    });
 704	    let recent_count = Memo::new(move |_| {
 705	        sessions
 706	            .get()
 707	            .iter()
 708	            .filter(|session| !session.is_focused && session.priority == IslandPriority::Recent)
 709	            .count()
 710	    });
 711	    let chip_status = move || {
 712	        let needs_human = needs_human_count.get();
 713	        let running = running_count.get();
 714	        if needs_human == 1 {
 715	            "1 needs attention".to_string()
 716	        } else if needs_human > 1 {
 717	            format!("{needs_human} need attention")
 718	        } else if running > 0 {
 719	            format!("{running} running")
 720	        } else {
 721	            format!("{} recent", recent_count.get())
 722	        }
 723	    };
 724	    let attention_announcement = move || {
 725	        let needs_human = needs_human_count.get();
 726	        let running = running_count.get();
 727	        if needs_human > 0 {
 728	            format!("{needs_human} Island items need attention")
 729	        } else if running > 0 {
 730	            format!("{running} Island items running")
 731	        } else {
 732	            String::new()
 733	        }
 734	    };
 735	    let chip_label = move || {
 736	        let state = chip_status();
 737	        focused_session.get().map_or_else(
 738	            || format!("Ocean, no focused session. {state}. Open session browser"),
 739	            |session| {
 740	                let project = session
 741	                    .project
 742	                    .as_deref()
 743	                    .map(|value| format!(", {value}"))
 744	                    .unwrap_or_default();
 745	                format!(
 746	                    "Focused session: {}{}. {}. Open session browser",
 747	                    session.title, project, state
 748	                )
 749	            },
 750	        )
 751	    };
 752	
 753	    view! {
 754	        <section class="island-host" on:keydown=on_keydown>
 755	            <button
 756	                class=move || {
 757	                    if needs_human_count.get() > 0 {
 758	                        "island-chip is-attention"
 759	                    } else if running_count.get() > 0 {
 760	                        "island-chip is-running"
 760	                        "island-chip is-running"
 761	                    } else {
 762	                        "island-chip"
 763	                    }
 764	                }
 765	                type="button"
 766	                node_ref=chip_ref
 767	                aria-label=chip_label
 768	                aria-haspopup="dialog"
 769	                aria-expanded=move || (mode.get() != IslandMode::Closed).to_string()
 770	                aria-controls="island-popover"
 771	                on:click=move |_| {
 772	                    if mode.get_untracked() == IslandMode::Closed {
 773	                        on_open.run(IslandMode::Browse);
 774	                    } else {
 775	                        close();
 776	                    }
 777	                }
 778	            >
 779	                <span
 780	                    class=move || {
 781	                        if needs_human_count.get() > 0 {
 782	                            "island-chip__dot is-attention"
 783	                        } else if running_count.get() > 0 {
 784	                            "island-chip__dot is-running"
 785	                        } else if focused_session.get().is_none() {
 786	                            "island-chip__dot is-empty"
 787	                        } else {
 788	                            "island-chip__dot"
 789	                        }
 790	                    }
 791	                    aria-hidden="true"
 792	                ></span>
 793	                <span class="island-chip__title">
 794	                    {move || focused_session.get().map(|item| item.title).unwrap_or_else(|| "Ocean · no session".into())}
 795	                </span>
 796	                <Show when=move || focused_session.get().and_then(|item| item.project).is_some()>
 797	                    <span class="island-chip__separator" aria-hidden="true">"·"</span>
 798	                    <span class="island-chip__project">
 799	                        {move || focused_session.get().and_then(|item| item.project).unwrap_or_default()}
 800	                    </span>
 801	                </Show>
 802	                <span class="island-chip__separator" aria-hidden="true">"·"</span>
 803	                <span class="island-chip__count">{move || chip_status()}</span>
 804	            </button>
 805	            <span class="island-live" aria-live="polite" aria-atomic="true">
 806	                {move || attention_announcement()}
 807	            </span>
 808	
 809	            <Show when=move || mode.get() != IslandMode::Closed>
 810	                <div class="island-scrim" aria-hidden="true" on:click=move |_| close()></div>
 811	                <section
 812	                    id="island-popover"
 813	                    class="island-popover"
 814	                    node_ref=popover_ref
 815	                    role="dialog"
 816	                    aria-modal="true"
 817	                    aria-label="Focus a session"
 818	                >
 819	                    <div class="island-search">
 820	                        <input
 821	                            class="island-search__input"
 822	                            type="search"
 823	                            role="combobox"
 824	                            aria-label="Search sessions"
 825	                            aria-autocomplete="list"
 826	                            aria-expanded="true"
 827	                            aria-controls="island-results"
 828	                            aria-activedescendant=move || {
 829	                                let id = selected_option_id();
 830	                                (!id.is_empty()).then_some(id)
 831	                            }
 832	                            placeholder="Search sessions, projects, paths, branches…"
 833	                            autocomplete="off"
 834	                            node_ref=input_ref
 835	                            prop:value=move || query.get()
 836	                            on:input=move |event| {
 837	                                query.set(event_target_value(&event));
 838	                                selected_index.set(0);
 839	                            }
 840	                        />
 841	                    </div>
 842	                    <Show when=move || !attention_items.get().is_empty()>
 843	                        <section class="island-attention" aria-labelledby="island-attention-title">
 844	                            <header class="island-attention__header">
 845	                                <span id="island-attention-title">"Activity"</span>
 846	                                <span>{move || {
 847	                                    let count = attention_items.get().len();
 848	                                    if count == 1 {
 849	                                        "1 item".to_string()
 850	                                    } else {
 851	                                        format!("{count} items")
 852	                                    }
 853	                                }}</span>
 854	                            </header>
 855	                            <div class="island-attention__list">
 856	                                <For
 857	                                    each=move || attention_items.get()
 858	                                    key=|item| item.id.clone()
 859	                                    children=move |item| {
 860	                                        let item_class = format!(
 861	                                            "island-attention__item {}",
 862	                                            item.state.class_name(),
 863	                                        );
 864	                                        let item_id_for_aria = item.id.clone();
 865	                                        let item_id_for_show = item.id.clone();
 866	                                        let item_id_for_toggle = item.id.clone();
 867	                                        let panel_id = attention_panel_id(&item.id);
 868	                                        let panel_id_for_control = panel_id.clone();
 869	                                        let panel_id_value = StoredValue::new_local(panel_id);
 870	                                        let state_label = item.state.label();
 871	                                        let session_title = item.session_title.clone();
 872	                                        let summary_detail = item.detail.clone();
 873	                                        let detail_text = StoredValue::new_local(item.detail.clone());
 874	                                        let detail_project = StoredValue::new_local(
 875	                                            item.project.clone().unwrap_or_default(),
 876	                                        );
 877	                                        let detail_tool = StoredValue::new_local(
 878	                                            item.tool.clone().unwrap_or_default(),
 879	                                        );
 880	                                        let detail_time = StoredValue::new_local(
 881	                                            if item.updated_at.is_empty() {
 882	                                                String::new()
 883	                                            } else {
 884	                                                fmt_relative_time(&item.updated_at)
 885	                                            },
 886	                                        );
 887	                                        let open_disabled = item.session_id.is_none();
 888	                                        let open_target = StoredValue::new_local((
 889	                                            item.session_id.clone(),
 890	                                            item.session_title.clone(),
 891	                                        ));
 892	                                        view! {
 893	                                            <article class=item_class>
 894	                                                <button
 895	                                                    class="island-attention__summary"
 896	                                                    type="button"
 897	                                                    aria-expanded=move || {
 898	                                                        (expanded_attention.get().as_deref()
 899	                                                            == Some(item_id_for_aria.as_str()))
 900	                                                            .to_string()
 901	                                                    }
 902	                                                    aria-controls=panel_id_for_control
 903	                                                    on:click=move |_| {
 904	                                                        expanded_attention.update(|expanded| {
 905	                                                            if expanded.as_deref()
 906	                                                                == Some(item_id_for_toggle.as_str())
 907	                                                            {
 908	                                                                *expanded = None;
 909	                                                            } else {
 910	                                                                *expanded = Some(item_id_for_toggle.clone());
 911	                                                            }
 912	                                                        });
 913	                                                    }
 914	                                                >
 915	                                                    <span class="island-attention__state">
 916	                                                        <span aria-hidden="true"></span>
