   1	//! Daemon connection layer.
   2	//!
   3	//! Single point of contact between the UI and `ocean-daemon`. We speak the
   4	//! product agent API:
   5	//!
   6	//!   POST /v1/agent/turns   → start a turn (returns metadata only)
   7	//!   GET  /v1/agent/events  → SSE stream of AgentTurnEvent
   8	//!   GET  /v1/agent/sessions → list sessions
   9	//!
  10	//! All reply text and tool output arrives as events on the SSE stream; the
  11	//! POST returns once the turn completes but carries no payload beyond
  12	//! turn_id / session_id / status. We push events into a Leptos signal so
  13	//! the rest of the UI reacts naturally.
  14	
  15	use std::collections::VecDeque;
  16	#[cfg(target_arch = "wasm32")]
  17	use std::sync::{Arc, Mutex};
  18	
  19	use futures_util::StreamExt;
  20	use gloo_net::eventsource::futures::EventSource;
  21	use gloo_net::http::Request;
  22	use leptos::prelude::*;
  23	#[cfg(target_arch = "wasm32")]
  24	use send_wrapper::SendWrapper;
  25	use serde::{Deserialize, Serialize};
  26	use serde_json::{json, Value};
  27	use wasm_bindgen::JsCast;
  28	use wasm_bindgen_futures::spawn_local;
  29	
  30	use crate::canvas::CanvasContext;
  31	use crate::model::{Block, ComponentPlacement, Role, ToolStatus, Turn};
  32	
  33	pub const DEFAULT_DAEMON_URL: &str = "http://127.0.0.1:4780";
  34	
  35	// Browsers cap concurrent HTTP/1.1 connections per origin. Each focused
  36	// session owns two long-lived EventSource requests (agent events + permission
  37	// events), so merely generation-gating stale readers is not enough: an idle
  38	// stale stream never yields another frame, remains open, and eventually blocks
  39	// the snapshot request for a later session. Keep explicit handles so every
  40	// focus change can close both transports before opening their replacements.
  41	#[cfg(target_arch = "wasm32")]
  42	type EventSourceSlot = Arc<Mutex<Option<SendWrapper<EventSource>>>>;
  43	
  44	#[cfg(target_arch = "wasm32")]
  45	fn replace_event_source(slot: &EventSourceSlot, next: EventSource) {
  46	    let previous = slot
  47	        .lock()
  48	        .expect("event source slot poisoned")
  49	        .replace(SendWrapper::new(next));
  50	    if let Some(previous) = previous {
  51	        previous.take().close();
  52	    }
  53	}
  54	
  55	#[cfg(target_arch = "wasm32")]
  56	fn close_event_source(slot: &EventSourceSlot) {
  57	    let previous = slot.lock().expect("event source slot poisoned").take();
  58	    if let Some(previous) = previous {
  59	        previous.take().close();
  60	    }
  61	}
  62	
  63	/// The throwaway working directory for a projectless Chat session. Chat is
  64	/// deliberately NOT a project: it clears the project selection and pins the
  65	/// next lazy session's cwd to `/tmp` so the agent runs in a real directory
  66	/// without claiming ownership of one. A project session is the opposite — it
  67	/// keeps cwd untouched and lets the daemon resolve the project's
  68	/// `workspace_root` from the selected `project_id`. Keeping this as a named
  69	/// constant (rather than a bare literal) pins the distinction at the type
  70	/// level and lets the wire-helper test assert it.
  71	pub const CHAT_WORKSPACE_ROOT: &str = "/tmp";
  72	
  73	/// Default LiveKit room the header "Join room call" entry targets when no
  74	/// proxy config seeded one (native shell has no proxy in front). Mirrors the
  75	/// proxy's `DEFAULT_LIVEKIT_ROOM_ID`.
  76	const DEFAULT_LIVEKIT_ROOM_ID: &str = "project:surface-main";
  77	
  78	/// Shape of the proxy's GET /api/config — the zero-config bootstrap payload.
  79	#[derive(Debug, Clone, Deserialize)]
  80	struct ProxyConfig {
 740	            | AgentEvent::AssistantTextDelta { session_id, .. }
 741	            | AgentEvent::ThinkingDelta { session_id, .. }
 742	            | AgentEvent::ToolCallStarted { session_id, .. }
 743	            | AgentEvent::ToolCallChunk { session_id, .. }
 744	            | AgentEvent::ToolCallFinished { session_id, .. }
 745	            | AgentEvent::TurnFinished { session_id, .. }
 746	            | AgentEvent::ComponentRender { session_id, .. }
 747	            | AgentEvent::ComponentUnmount { session_id, .. }
 748	            | AgentEvent::BrowserActivity { session_id, .. }
 749	            | AgentEvent::SurfacePatch { session_id, .. } => session_id.as_str(),
 750	            // An extension event's scope (when set) is its session id; a
 751	            // council-wide one has no scope and is treated as unscoped.
 752	            AgentEvent::Extension { scope, .. } => scope.as_deref().unwrap_or(""),
 753	            AgentEvent::Other => return None,
 754	        };
 755	        (!sid.is_empty()).then_some(sid)
 756	    }
 757	}
