1749	    /// Open the SSE stream and pipe events into the turns signal. Reconnects
1750	    /// on disconnect with a small backoff. Spawned once per session.
1751	    pub fn connect(&self) {
1752	        let url = self.url.get_untracked();
1753	        let turns = self.turns;
1754	        let streaming = self.streaming;
1755	        let session_id = self.session_id;
1756	        let status = self.status;
1757	        let status_detail = self.status_detail;
1758	        let sse_generation = self.sse_generation;
1759	        let last_turn_tokens = self.last_turn_tokens;
1760	        let session_tokens = self.session_tokens;
1761	        let model = self.model;
1762	        let active_turn_id = self.active_turn_id;
1763	        let browser_active = self.browser_active;
1764	        let browser_last_action = self.browser_last_action;
1765	        let canvas_patches = self.canvas_patches;
1766	        let awaiting_session_adoption = self.awaiting_session_adoption;
1767	        // Captured so the reconnect path can re-hydrate the transcript (and
1768	        // restore title/cwd) after a stream gap — see the rehydrate call below.
1769	        let session_title = self.session_title;
1770	        let cwd = self.cwd;
1771	        let pinned_widgets = self.pinned_widgets;
1772	        #[cfg(target_arch = "wasm32")]
1773	        let agent_event_source = Arc::clone(&self.agent_event_source);
1774	
1775	        let generation = sse_generation.get_untracked().wrapping_add(1);
1776	        sse_generation.set(generation);
1777	        #[cfg(target_arch = "wasm32")]
1778	        {
1779	            close_event_source(&self.agent_event_source);
1780	            close_event_source(&self.permission_event_source);
1781	        }
1782	        let Some(active_session_id) = session_id.get_untracked() else {
1783	            status.set("new session".into());
1784	            return;
1785	        };
1786	        let seen_sse_ids: RwSignal<VecDeque<String>> = RwSignal::new(VecDeque::new());
1787	
1788	        // Permission requests ride a SEPARATE stream. The product event stream
1789	        // `/v1/agent/events` only carries `AgentTurnEvent` types and serializes
1790	        // the inner event (no `permission_id`). The daemon emits
1791	        // `OceanEvent::PermissionRequest` — with the envelope's `permission_id`
1792	        // — onto the control stream `/v1/events`. Open that too, scoped to this
1793	        // session/generation, so a gated mutating turn surfaces an approval card
1794	        // instead of hanging. Decisions clear on `permission_decision` here.
1795	        self.connect_permission_stream(active_session_id.clone(), generation);
1796	
1797	        spawn_local(async move {
1798	            // SSE is a live tail: the daemon does NOT replay frames emitted
1799	            // while the client was disconnected. The FIRST open of this
1800	            // generation is paired with a fresh transcript that the caller has
1801	            // already hydrated (new/switch/create), so it needs no recovery.
1802	            // Every RE-open after a drop, though, has a gap — any delta /
1803	            // tool-call / turn_finished emitted during the outage is gone. So on
1804	            // each reconnect we re-fetch the session snapshot (OCEAN-72's
1805	            // hydration) to recover the missed events instead of leaving the UI
1806	            // permanently stale/truncated (OCEAN-104).
1807	            let mut connected_once = false;
1808	
1809	            loop {
1810	                if sse_generation.get_untracked() != generation {
1811	                    break;
1812	                }
1813	
1814	                // On a reconnect (not the first open) the live tail had a gap.
1815	                // Re-hydrate the transcript from the daemon so missed events are
1816	                // recovered, and clear any stuck `streaming` state — if the turn
1817	                // finished during the outage, the `turn_finished` frame that
1818	                // would have flipped `streaming` off never arrives, so without
1819	                // this the composer's Stop button (and the streaming gate) stay
1820	                // stuck on forever.
1821	                if connected_once {
1822	                    if streaming.get_untracked() {
1823	                        // The in-flight turn's terminal frame may have been lost
1824	                        // in the gap. Drop the stuck streaming state now; the
1825	                        // re-hydrate below restores the true transcript, and if
1826	                        // the turn is genuinely still running its live frames
1827	                        // resume on the fresh stream.
1828	                        streaming.set(false);
1829	                        active_turn_id.set(None);
1830	                    }
1831	                    rehydrate_transcript(
1832	                        url.clone(),
1833	                        active_session_id.clone(),
1834	                        turns,
1835	                        session_id,
1836	                        session_title,
1837	                        cwd,
1838	                        model,
1839	                        pinned_widgets,
1840	                    )
1841	                    .await;
1842	                }
1843	
1844	                let events_url = format!(
1845	                    "{}/v1/agent/events?session_id={}",
1846	                    url.trim_end_matches('/'),
1847	                    active_session_id.as_str()
1848	                );
1849	                status.set(if connected_once {
1850	                    "reconnecting…".into()
1851	                } else {
1852	                    "connecting…".to_string()
1853	                });
1854	                let mut es = match EventSource::new(&events_url) {
1855	                    Ok(es) => es,
1856	                    Err(err) => {
1857	                        let raw = err.to_string();
1858	                        log::error!("sse connect error: {raw}");
1859	                        status.set(format!("sse connect error: {}", concise_error(&raw)));
1860	                        gloo_timers::future::TimeoutFuture::new(2_000).await;
1861	                        continue;
1862	                    }
1863	                };
1864	                #[cfg(target_arch = "wasm32")]
1865	                replace_event_source(&agent_event_source, es.clone());
1866	                status.set("connected".into());
1867	                status_detail.set(None);
1868	                // Mark that we have opened the stream at least once for this
1869	                // generation. From here on, any loop re-entry is a reconnect and
1870	                // triggers the re-hydrate/stuck-streaming recovery at the top.
1871	                connected_once = true;
1872	
1873	                // EventSource delivers events by `event:` name. The daemon
1874	                // names each frame by its AgentTurnEvent type, so we subscribe
1875	                // per type and merge the streams. gloo-net has no
1876	                // `subscribe_multiple`; we build the merged stream ourselves
1877	                // with `futures::stream::select_all`. The name list is the
1878	                // single source of truth `AGENT_EVENT_NAMES` (see its doc
1879	                // comment — it MUST mirror the daemon's emitted names, and a
1880	                // test guards against drift).
1881	                let mut subs = Vec::with_capacity(AGENT_EVENT_NAMES.len());
1882	                let mut sub_err = None;
1883	                for name in AGENT_EVENT_NAMES {
1884	                    match es.subscribe(*name) {
1885	                        Ok(s) => subs.push(s),
1985	                // Brief backoff before re-opening. The status flips to
1986	                // "reconnecting…" and the transcript re-hydrates at the top of
1987	                // the next iteration (gated on `connected_once`).
1988	                status.set("reconnecting…".into());
1989	                gloo_timers::future::TimeoutFuture::new(1_000).await;
1990	            }
1991	        });
1992	    }
1993	
1994	    /// Subscribe to the daemon's control stream `/v1/events` for permission
1995	    /// frames, scoped to `active_session_id` and the current SSE `generation`.
1996	    ///
1997	    /// `EventSource` delivers frames by their `event:` name, so we subscribe to
1998	    /// `permission_request` and `permission_decision` by name (the same per-name
1999	    /// pattern the agent stream uses). The control stream is NOT session-scoped
2000	    /// server-side, so we drop any frame whose envelope `session_id` isn't ours.
2001	    /// When gating is off the daemon never emits these, so this stream just sits
2002	    /// idle — no behavior change for the ungated path.
2003	    fn connect_permission_stream(&self, active_session_id: String, generation: u64) {
2004	        let url = self.url.get_untracked();
2005	        let sse_generation = self.sse_generation;
2006	        let pending = self.pending_permissions;
2007	        #[cfg(target_arch = "wasm32")]
2008	        let permission_event_source = Arc::clone(&self.permission_event_source);
2009	
2010	        spawn_local(async move {
2011	            loop {
2012	                if sse_generation.get_untracked() != generation {
2013	                    break;
2014	                }
2015	                let events_url = format!("{}/v1/events", url.trim_end_matches('/'));
2016	                let mut es = match EventSource::new(&events_url) {
2017	                    Ok(es) => es,
2018	                    Err(_) => {
2019	                        gloo_timers::future::TimeoutFuture::new(2_000).await;
2020	                        continue;
2021	                    }
2022	                };
2023	                #[cfg(target_arch = "wasm32")]
2024	                replace_event_source(&permission_event_source, es.clone());
2025	
2026	                let mut subs = Vec::new();
2027	                let mut sub_err = false;
2028	                for name in ["permission_request", "permission_decision"] {
2029	                    match es.subscribe(name) {
2030	                        Ok(s) => subs.push(s),
2031	                        Err(_) => {
2032	                            sub_err = true;
2033	                            break;
2034	                        }
2035	                    }
2036	                }
2037	                if sub_err {
2038	                    gloo_timers::future::TimeoutFuture::new(2_000).await;
2039	                    continue;
2040	                }
2041	
2042	                let mut stream = futures_util::stream::select_all(subs);
2043	                while let Some(msg) = stream.next().await {
2044	                    if sse_generation.get_untracked() != generation {
2045	                        break;
2046	                    }
2047	                    let Ok((_event_name, msg)) = msg else {
2048	                        continue;
2049	                    };
2050	                    let Some(data) = msg.data().as_string() else {
2051	                        continue;
2052	                    };
2053	                    let Ok(evt) = serde_json::from_str::<ControlEvent>(&data) else {
2054	                        continue;
2055	                    };
2570	                            }
2571	                        }
2572	                        Ok(_) => {
2573	                            log::warn!("sessions fetch not ok");
2574	                            break;
2575	                        }
2576	                        Err(err) => {
2577	                            log::warn!("sessions decode error: {err}");
2578	                            break;
2579	                        }
2580	                    },
2581	                    Err(err) => {
2582	                        log::warn!("sessions fetch error: {err}");
2583	                        break;
2584	                    }
2585	                }
2586	            }
2587	            session_list.set(all);
2588	        });
2589	    }
