2608	        let request_list = self.request_list;
2609	        let permission_list = self.permission_list;
2610	        let attention_fetching = self.attention_fetching;
2611	        spawn_local(async move {
2612	            #[derive(Deserialize)]
2613	            struct RequestsResponse {
2614	                ok: bool,
2615	                #[serde(default)]
2616	                requests: Vec<RequestSnapshot>,
2617	            }
2618	            #[derive(Deserialize)]
2619	            struct PermissionsResponse {
